def is_floating_panel_alive():
    global FLOATING_PANEL
    if FLOATING_PANEL is None:
        return False
    try:
        return bool(FLOATING_PANEL.winfo_exists())
    except:
        return False

def update_status_threadsafe(lbl_status, text, color, detail_text="", lbl_detail=None):
    if ROOT_WINDOW and lbl_status:
        try:
            def _update():
                lbl_status.config(text=text, fg=color)
                if lbl_detail:
                    detail_fg = color if color != "#ef4444" else "#f87171"
                    lbl_detail.config(text=detail_text, fg=detail_fg)
            ROOT_WINDOW.after(0, _update)
        except:
            pass



def get_apollo_serials():
    serials = []
    try:
        import winreg
        for path in [r"SYSTEM\GESCOM", r"SYSTEM\Wow6432Node\GESCOM"]:
            try:
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, path, 0, winreg.KEY_READ) as key:
                    i = 0
                    while True:
                        try:
                            val_name, val_data, val_type = winreg.EnumValue(key, i)
                            if val_data and isinstance(val_data, str):
                                clean_val = val_data.strip()
                                if clean_val and clean_val not in serials:
                                    serials.append(clean_val)
                            i += 1
                        except OSError:
                            break
            except Exception:
                pass
    except Exception:
        pass
    return serials


