def send_ws_message_threadsafe(payload):
    global ACTIVE_WEBSOCKET, ASYNC_LOOP
    if ACTIVE_WEBSOCKET and ASYNC_LOOP:
        async def send_task():
            try:
                await ACTIVE_WEBSOCKET.send(json.dumps(payload))
            except Exception as e:
                print(f"Error enviando mensaje WS: {e}")
        asyncio.run_coroutine_threadsafe(send_task(), ASYNC_LOOP)

LAST_LOCAL_CLIPBOARD = ""

def set_clipboard_text(text):
    global LAST_LOCAL_CLIPBOARD
    try:
        LAST_LOCAL_CLIPBOARD = text
        # SincronizaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n nativa de bajo nivel del Portapapeles de Windows (SÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âºper robusto y asÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­ncrono)
        import ctypes
        if ctypes.windll.user32.OpenClipboard(None):
            try:
                ctypes.windll.user32.EmptyClipboard()
                text_bytes = text.encode('utf-16-le') + b'\x00\x00'
                h_global_mem = ctypes.windll.kernel32.GlobalAlloc(0x0002, len(text_bytes))
                if h_global_mem:
                    lp_global_mem = ctypes.windll.kernel32.GlobalLock(h_global_mem)
                    ctypes.memmove(lp_global_mem, text_bytes, len(text_bytes))
                    ctypes.windll.kernel32.GlobalUnlock(h_global_mem)
                    # CF_UNICODETEXT = 13
                    ctypes.windll.user32.SetClipboardData(13, h_global_mem)
            finally:
                ctypes.windll.user32.CloseClipboard()
        
        # SincronizaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n secundaria en Tkinter
        if ROOT_WINDOW:
            try:
                ROOT_WINDOW.clipboard_clear()
                ROOT_WINDOW.clipboard_append(text)
                ROOT_WINDOW.update()
            except:
                pass
        print("[CLIPBOARD] Portapapeles sincronizado con ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©xito nativamente en Windows.")
    except Exception as e:
        print(f"[CLIPBOARD] Error en set_clipboard_text: {e}")

def is_running_as_service():
    """
    Detecta si estamos corriendo en Session 0 (servicio Windows sin escritorio).
    Usa ProcessIdToSessionId como mÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©todo primario ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â es el mÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡s confiable:
      Session 0 = proceso de servicio (sin UI)
      Session >= 1 = sesiÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n interactiva del usuario (UI permitida)
    """
    try:
        import ctypes
        pid = ctypes.windll.kernel32.GetCurrentProcessId()
        session_id = ctypes.c_ulong(0)
        ctypes.windll.kernel32.ProcessIdToSessionId(pid, ctypes.byref(session_id))
        if session_id.value == 0:
            return True  # Session 0 = definitivamente un servicio
        # Session >= 1: proceso en sesiÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n interactiva ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ tiene UI
        return False
    except Exception:
        return False


def manage_service(action: str):
    """Instala, desinstala, inicia o detiene el servicio de Windows de forma robusta."""
    import subprocess
    import sys

    if getattr(sys, 'frozen', False):
        exe_path = f'"{sys.executable}"'
    else:
        python_exe = sys.executable
        # Preferir pythonw.exe para no abrir consola
        pythonw = python_exe.replace('python.exe', 'pythonw.exe')
        if not os.path.exists(pythonw):
            pythonw = python_exe
        script = os.path.abspath(__file__)
        exe_path = f'"{pythonw}" "{script}"'

    def run_sc(*args):
        # Usar la ruta completa a sc.exe de System32 para evitar redirecciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n WoW64
        # cuando el proceso es 32-bit corriendo en Windows 64-bit
        windir = os.environ.get('SystemRoot', 'C:\\Windows')
        sc_exe = os.path.join(windir, 'System32', 'sc.exe')
        # Si el proceso es x86 en OS x64, acceder a System32 nativo via Sysnative
        sysnative = os.path.join(windir, 'Sysnative', 'sc.exe')
        if os.path.exists(sysnative):
            sc_exe = sysnative
        cmd = [sc_exe] + list(args)
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=15, creationflags=0x08000000 if os.name == 'nt' else 0)
            return result.returncode == 0, result.stdout + result.stderr
        except Exception as e:
            return False, str(e)

    if action == 'install':
        # Borrar instancia previa si existe para evitar conflictos
        run_sc('stop', SERVICE_NAME)
        import time; time.sleep(1)
        run_sc('delete', SERVICE_NAME)
        import time; time.sleep(1)

        ok, out = run_sc(
            'create', SERVICE_NAME,
            'binPath=', exe_path,
            'start=', 'auto',
            'obj=', 'LocalSystem',
            'DisplayName=', SERVICE_DISPLAY
        )
        if ok:
            # PolÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­tica de recuperaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n: reiniciar despuÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©s de 30s en el primer fallo,
            # 60s en el segundo, y 120s en fallos posteriores. Reset contador cada hora.
            run_sc('failure', SERVICE_NAME,
                   'reset=', '3600',
                   'actions=', 'restart/30000/restart/60000/restart/120000')
            run_sc('start', SERVICE_NAME)
            print(f"[SERVICE] Servicio '{SERVICE_DISPLAY}' instalado e iniciado con ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©xito.")
            return True, "Instalado e iniciado."
        else:
            print(f"[SERVICE] Error instalando: {out}")
            return False, out

    elif action == 'uninstall':
        run_sc('stop', SERVICE_NAME)
        import time; time.sleep(2)
        ok, out = run_sc('delete', SERVICE_NAME)
        print(f"[SERVICE] Desinstalado: {out}")
        return ok, out

    elif action == 'start':
        ok, out = run_sc('start', SERVICE_NAME)
        return ok, out

    elif action == 'stop':
        ok, out = run_sc('stop', SERVICE_NAME)
        return ok, out

    return False, 'AcciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n desconocida'


